// Mengambil data dari node GET Jadwal Aktif
const jadwalData = $input.first().json.data;
const results = [];
const jurusanId = "3e41ce1d-af1b-4d2c-80e1-46f6dd261403";

for (const jadwal of jadwalData) {
    const jadwalId = jadwal.id;
    const mapel = jadwal.alias;

    for (const grup of (jadwal.group || [])) {
        let namaKelas = grup.name;
        if (namaKelas.startsWith("lt-")) {
            namaKelas = namaKelas.replace("lt-", "");
        }

        results.push({
            json: {
                mapel: mapel,
                kelas: namaKelas,
                group_id: grup.id,
                jadwal_id: jadwalId,
                jurusan_ids: jurusanId,
                page: 1
            }
        });
    }
}

return results;

const results = [];
const items = $input.all(); 

for (let i = 0; i < items.length; i++) {
    const prevInfo = $("Ekstrak Daftar Kelas").all()[i].json;
    const kelas = prevInfo.kelas;
    const mapel = prevInfo.mapel || "-";

    let dataSiswa = [];
    if (items[i].json.data && Array.isArray(items[i].json.data.data)) {
        dataSiswa = items[i].json.data.data;
    } else if (Array.isArray(items[i].json.data)) {
        dataSiswa = items[i].json.data;
    } else if (Array.isArray(items[i].json)) {
        dataSiswa = items[i].json;
    }

    for (const peserta of dataSiswa) {
        let rawNilai = peserta.check_point !== undefined ? peserta.check_point : 0;
        let finalNilai = rawNilai;
        if (typeof rawNilai === "string") {
            rawNilai = rawNilai.replace(",", ".").trim();
        }
        const num = Number(rawNilai);
        if (!isNaN(num) && rawNilai !== "" && rawNilai !== null) {
            finalNilai = Math.round(num);
        }
        results.push({
            json: {
                mata_pelajaran: mapel,
                kelas: kelas, 
                no_ujian: peserta.peserta ? peserta.peserta.no_ujian : "-",
                nama: peserta.peserta ? peserta.peserta.name : "-",
                nilai: finalNilai
            }
        });
    }
}

return results;

// Mengambil semua 146 data dari node sebelumnya
const allData = $input.all().map(item => item.json);

// 1. Mengelompokkan data berdasarkan 'kelas'
const groupedData = {};
for (const row of allData) {
    if (!groupedData[row.kelas]) {
        groupedData[row.kelas] = [];
    }
    groupedData[row.kelas].push(row);
}

// 2. Membuat output HTML untuk masing-masing kelas
const output = [];
for (const kelas in groupedData) {
    const siswaList = groupedData[kelas];

    // Menyusun baris tabel untuk setiap siswa
    let tableRows = "";
    siswaList.forEach((siswa, index) => {
        tableRows += `
        <tr>
            <td style="text-align: center;">${index + 1}</td>
            <td>${siswa.no_ujian}</td>
            <td>${siswa.nama}</td>
            <td style="text-align: center;">${siswa.hasil_akhir}</td>
        </tr>`;
    });

    // Menggabungkan ke dalam template HTML lengkap
    const html = `
    <!DOCTYPE html>
    <html>
    <head>
    <style>
        body { font-family: 'Helvetica', 'Arial', sans-serif; color: #333; }
        .header { text-align: center; margin-bottom: 20px; border-bottom: 2px solid #2c3e50; padding-bottom: 10px; }
        .header h1 { font-size: 20pt; margin: 0 0 5px 0; }
        .header h2 { font-size: 14pt; margin: 0; font-weight: normal; }
        table { width: 100%; border-collapse: collapse; margin-top: 10px; }
        th, td { padding: 8px; border: 1px solid #000; }
        th { background-color: #2c3e50; color: #fff; text-align: center; }
        tr:nth-child(even) { background-color: #f9f9f9; }
    </style>
    </head>
    <body>
        <div class="header">
            <h1>DAFTAR HASIL UJIAN</h1>
            <h2>Kelas ${kelas}</h2>
        </div>
        <table>
            <thead>
                <tr>
                    <th style="width: 5%;">No</th>
                    <th style="width: 25%;">No Ujian</th>
                    <th style="width: 55%;">Nama</th>
                    <th style="width: 15%;">Hasil Akhir</th>
                </tr>
            </thead>
            <tbody>
                ${tableRows}
            </tbody>
        </table>
    </body>
    </html>`;
    // Mendorong hasilnya sebagai item baru
    output.push({
        json: {
            filename: `Nilai_${kelas}.pdf`,
            kelas: kelas,
            html: html
        }
    });
}

return output;

